contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(value > 0);
        require(address(this).balance >= value);

        uint256 balBefore = address(c).balance;
        uint256 callerBefore = address(this).balance;
        uint256 depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        if (reverted) {
            assert(address(c).balance == balBefore);
        } else {
            assert(address(c).balance == 0);
            assert(address(this).balance == callerBefore + balBefore);
        }
        assert(c.depositsCount() == depositsBefore);
    }
}

