pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(value > 0);
        vm.assume(address(this).balance >= value);
        uint256 balBefore = address(c).balance;
        uint256 callerBefore = address(this).balance;
        uint256 depositsBefore;
        try c.depositsCount() returns (uint256 __r) { depositsBefore = __r; } catch { return; }
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        if (reverted) {
            assert(address(c).balance == balBefore);
        } else {
            assert(address(c).balance == 0);
            assert(address(this).balance == callerBefore + balBefore);
        }
        assertTrue(c.depositsCount() == depositsBefore);
    }

    function testFuzz_run(uint256 value) public {
        _run(value);
    }

    receive() external payable {}
}
